-- TF2025 历史销售事件批量重配（2026-11-21）
-- 处理 484 组后续销售。每条记录均有旧站事件、手机号客户档案和云端目标销售行。
-- 执行器读取 precheck_passed 后，只有值为 1 才提交，否则回滚。
START TRANSACTION;
CREATE TEMPORARY TABLE tf2025_sale_event_reassign_batch_20261121 (target_sale_id BIGINT NOT NULL PRIMARY KEY,target_device_id BIGINT NOT NULL,serial_number VARCHAR(100) NOT NULL,old_customer_id BIGINT NOT NULL,old_sale_time DATETIME NOT NULL,old_sale_price DECIMAL(10,2) NOT NULL,old_invoice_number VARCHAR(100) NOT NULL,new_customer_id BIGINT NOT NULL,new_phone VARCHAR(30) NOT NULL,new_sale_time DATETIME NOT NULL,new_inventory_time DATETIME NOT NULL,new_sale_price DECIMAL(10,2) NOT NULL,new_invoice_number VARCHAR(100) NOT NULL,new_brand_id INT NULL,new_model_id INT NULL,new_color_id INT NULL,new_memory_id INT NULL,old_device_sale_time DATETIME NULL,old_device_sale_price DECIMAL(10,2) NULL,old_device_is_new TINYINT NULL,old_inventory_time DATETIME NULL,old_brand_id INT NULL,old_model_id INT NULL,old_color_id INT NULL,old_memory_id INT NULL);
CREATE TEMPORARY TABLE tf2025_sale_event_reassign_batch_20261121_seq (sequence_date CHAR(8) NOT NULL PRIMARY KEY,expected_current_sequence INT UNSIGNED NOT NULL,target_sequence INT UNSIGNED NOT NULL);
SELECT sequence_date,'XS',expected_current_sequence FROM tf2025_sale_event_reassign_batch_20261121_seq;
SELECT sequence_date,current_sequence FROM invoice_sequences
WHERE type_suffix='XS' AND BINARY sequence_date IN (SELECT BINARY sequence_date FROM tf2025_sale_event_reassign_batch_20261121_seq)
ORDER BY sequence_date FOR UPDATE;
SET @precheck_passed := 1;
SELECT @precheck_passed := IF(COUNT(*)=484,@precheck_passed,0) FROM tf2025_sale_event_reassign_batch_20261121;
SELECT @precheck_passed := IF(COUNT(*)=484,@precheck_passed,0) FROM tf2025_sale_event_reassign_batch_20261121 b JOIN sales s ON s.id=b.target_sale_id JOIN phones p ON p.id=s.phone_id AND p.id=b.target_device_id WHERE BINARY p.serial_number=BINARY b.serial_number AND s.customer_id=b.old_customer_id AND s.sale_time=b.old_sale_time AND s.sale_price=b.old_sale_price AND BINARY s.invoice_number=BINARY b.old_invoice_number AND s.status='completed' AND p.sale_time <=> b.old_device_sale_time AND p.sale_price <=> b.old_device_sale_price AND p.is_new <=> b.old_device_is_new AND p.inventory_time <=> b.old_inventory_time AND p.brand_id <=> b.old_brand_id AND p.model_id <=> b.old_model_id AND p.color_id <=> b.old_color_id AND p.memory_id <=> b.old_memory_id;
SELECT @precheck_passed := IF(COUNT(*)=484,@precheck_passed,0) FROM tf2025_sale_event_reassign_batch_20261121 b JOIN customers c ON c.id=b.new_customer_id AND BINARY c.phone=BINARY b.new_phone AND c.status=1;
SELECT @precheck_passed := IF(COUNT(*)=0,@precheck_passed,0) FROM tf2025_sale_event_reassign_batch_20261121 b LEFT JOIN brands x ON x.id=b.new_brand_id AND x.status=1 WHERE b.new_brand_id IS NOT NULL AND x.id IS NULL;
SELECT @precheck_passed := IF(COUNT(*)=0,@precheck_passed,0) FROM tf2025_sale_event_reassign_batch_20261121 b LEFT JOIN models x ON x.id=b.new_model_id AND x.status=1 WHERE b.new_model_id IS NOT NULL AND x.id IS NULL;
SELECT @precheck_passed := IF(COUNT(*)=0,@precheck_passed,0) FROM tf2025_sale_event_reassign_batch_20261121 b LEFT JOIN colors x ON x.id=b.new_color_id AND x.status=1 WHERE b.new_color_id IS NOT NULL AND x.id IS NULL;
SELECT @precheck_passed := IF(COUNT(*)=0,@precheck_passed,0) FROM tf2025_sale_event_reassign_batch_20261121 b LEFT JOIN memories x ON x.id=b.new_memory_id AND x.status=1 WHERE b.new_memory_id IS NOT NULL AND x.id IS NULL;
SELECT @precheck_passed := IF(COUNT(*)=0,@precheck_passed,0) FROM sales s JOIN tf2025_sale_event_reassign_batch_20261121 b ON BINARY s.invoice_number=BINARY b.new_invoice_number AND s.id<>b.target_sale_id;
SELECT @precheck_passed := IF(COUNT(*)=436,@precheck_passed,0) FROM tf2025_sale_event_reassign_batch_20261121_seq q JOIN invoice_sequences s ON BINARY s.sequence_date=BINARY q.sequence_date AND s.type_suffix='XS' AND s.current_sequence=q.expected_current_sequence;
SELECT @precheck_passed := IF(COUNT(*)=0,@precheck_passed,0) FROM national_subsidies n JOIN tf2025_sale_event_reassign_batch_20261121 b ON n.sale_id=b.target_sale_id OR n.phone_id=b.target_device_id;
SELECT @precheck_passed := IF(COUNT(*)=0,@precheck_passed,0) FROM payment_records n JOIN tf2025_sale_event_reassign_batch_20261121 b ON n.order_id=b.target_sale_id OR n.sales_order_id=b.target_sale_id;
SELECT @precheck_passed := IF(COUNT(*)=0,@precheck_passed,0) FROM sales_order_items n JOIN tf2025_sale_event_reassign_batch_20261121 b ON n.sale_id=b.target_sale_id OR n.phone_id=b.target_device_id OR n.linked_phone_sale_id=b.target_sale_id;
SELECT @precheck_passed := IF(COUNT(*)=0,@precheck_passed,0) FROM customer_account_entries n JOIN tf2025_sale_event_reassign_batch_20261121 b ON n.source_id=b.target_sale_id;
SELECT @precheck_passed := IF(COUNT(*)=0,@precheck_passed,0) FROM customer_film_services n JOIN tf2025_sale_event_reassign_batch_20261121 b ON n.qualification_sale_id=b.target_sale_id OR n.phone_id=b.target_device_id;
SELECT @precheck_passed := IF(COUNT(*)=0,@precheck_passed,0) FROM accessory_serials n JOIN tf2025_sale_event_reassign_batch_20261121 b ON n.sale_id=b.target_sale_id;
SELECT @precheck_passed := IF(COUNT(*)=0,@precheck_passed,0) FROM rentals n JOIN tf2025_sale_event_reassign_batch_20261121 b ON n.sale_id=b.target_sale_id OR n.phone_id=b.target_device_id;
SELECT @precheck_passed := IF(COUNT(*)=0,@precheck_passed,0) FROM repairs n JOIN tf2025_sale_event_reassign_batch_20261121 b ON n.phone_id=b.target_device_id;
SELECT @precheck_passed := IF(COUNT(*)=0,@precheck_passed,0) FROM preorders n JOIN tf2025_sale_event_reassign_batch_20261121 b ON n.sale_id=b.target_sale_id OR n.matched_phone_id=b.target_device_id;
SELECT @precheck_passed := IF(COUNT(*)=0,@precheck_passed,0) FROM sale_reversal_logs n JOIN tf2025_sale_event_reassign_batch_20261121 b ON n.phone_id=b.target_device_id OR n.original_sale_id=b.target_sale_id;
SELECT @precheck_passed AS precheck_passed;
UPDATE invoice_sequences s JOIN tf2025_sale_event_reassign_batch_20261121_seq b ON BINARY b.sequence_date=BINARY s.sequence_date AND s.type_suffix='XS' SET s.current_sequence=GREATEST(s.current_sequence,b.target_sequence) WHERE @precheck_passed=1;
UPDATE sales s JOIN tf2025_sale_event_reassign_batch_20261121 b ON b.target_sale_id=s.id SET s.customer_id=b.new_customer_id,s.sale_time=b.new_sale_time,s.sale_price=b.new_sale_price,s.invoice_number=b.new_invoice_number,s.remarks=CONCAT_WS('；',NULLIF(s.remarks,''),'历史重配：旧站与原始数据确认后续二手销售'),s.updated_at=NOW() WHERE @precheck_passed=1;
UPDATE phones p JOIN tf2025_sale_event_reassign_batch_20261121 b ON b.target_device_id=p.id SET p.sale_price=b.new_sale_price,p.sale_time=b.new_sale_time,p.inventory_time=b.new_inventory_time,p.is_new=0,p.brand_id=COALESCE(b.new_brand_id,p.brand_id),p.model_id=COALESCE(b.new_model_id,p.model_id),p.color_id=COALESCE(b.new_color_id,p.color_id),p.memory_id=COALESCE(b.new_memory_id,p.memory_id),p.remarks=CONCAT_WS('；',NULLIF(p.remarks,''),'历史重配：旧站与原始数据确认后续二手销售') WHERE @precheck_passed=1;
SELECT @precheck_passed AS precheck_passed;
SELECT COUNT(*) AS updated_sales FROM sales s JOIN tf2025_sale_event_reassign_batch_20261121 b ON b.target_sale_id=s.id AND s.customer_id=b.new_customer_id AND s.sale_time=b.new_sale_time AND s.sale_price=b.new_sale_price AND BINARY s.invoice_number=BINARY b.new_invoice_number;
SELECT COUNT(*) AS updated_devices FROM phones p JOIN tf2025_sale_event_reassign_batch_20261121 b ON b.target_device_id=p.id AND p.sale_time=b.new_sale_time AND p.inventory_time=b.new_inventory_time AND p.sale_price=b.new_sale_price AND p.is_new=0;
-- 由执行器确认 precheck_passed=1、updated_sales=484、updated_devices=484 后 COMMIT，否则 ROLLBACK。
